import { expect, Locator, Page, Request } from '@playwright/test';

export { qaChildName, annotateCleanup, createChild, openSharedUserPage } from '../placement-results/placement.helpers';

/** Регулярное выражение «конец адреса» для пути ребёнка: /<id>/home, /<id>/assessment/intro … */
export function childUrl(childId: string, tail: string): RegExp {
  return new RegExp(`/${childId}/${tail.replace(/\//g, '\\/')}$`);
}

/** Локаторы экранов C1 / C2 / C3. */
export function readingScreens(page: Page) {
  return {
    // C1
    introTitle: page.getByText('בואו נכיר!'),
    introCaption: page.getByText('כמה קטעים קצרים • כ־5 דקות'),
    start: page.getByRole('button', { name: 'מתחילים!', exact: true }),
    resume: page.getByRole('button', { name: 'ממשיכים!', exact: true }),
    later: page.getByRole('button', { name: 'אחר כך', exact: true }),
    // C2
    readingHeader: page.getByText(/מבדק התאמה\s*[•·]\s*קריאה/), // в Figma «·», в коде группы 1 — «•»
    passage: (n: number) => page.getByText(new RegExp(`קטע ${n}(?!\\d)`)),
    read: page.getByRole('button', { name: 'קראתי!', exact: true }), // кнопка микрофона, aria «קראתי!»
    retry: page.getByRole('button', { name: 'לנסות שוב', exact: true }),
    howWasIt: page.getByText('איך היה?'),
    pause: page.getByRole('button', { name: 'השהיה', exact: true }), // TODO verify selector (роль кнопки «השהיה»)
    // C3
    resultsTitle: page.getByText(/^כל הכבוד, /),
    resultsStart: page.getByRole('button', { name: 'יאללה, מתחילים!', exact: true }),
  };
}

/** Передать устройство ребёнку (/children/<id>/handover → «<имя>, בואו נתחיל!») и дождаться C1. */
export async function handoverToIntro(page: Page, childId: string, childName: string) {
  await page.goto(`/children/${childId}/handover`);
  await page.getByRole('button', { name: `${childName}, בואו נתחיל!` }).click();
  await page.waitForURL(childUrl(childId, 'assessment/intro'));
  await expect(readingScreens(page).introTitle).toBeVisible();
}

export type SelfRating = 'בסדר' | 'קל' | 'קשה' | 'לא בטוח/ה'; // «לא בטוח/ה» — для #976cbc

/** Один отрывок без голоса: «קראתי!» → «לא שומעים אותך כרגע» → «לנסות שוב» → «איך היה?» → оценка. */
export async function answerOnePassage(page: Page, rating: SelfRating = 'בסדר') {
  const s = readingScreens(page);
  await s.read.click();
  await expect(s.retry.or(s.howWasIt).first()).toBeVisible({ timeout: 30_000 });
  if (await s.retry.isVisible()) await s.retry.click();
  await expect(s.howWasIt).toBeVisible({ timeout: 30_000 });
  await page.getByRole('button', { name: rating, exact: true }).click(); // TODO verify selector (кнопки самооценки, кроме «בסדר»)
  await expect(s.howWasIt).toBeHidden({ timeout: 30_000 });
}

/**
 * Пройти чтение самооценкой до C3 (/<id>/assessment/results). Число отрывков заранее не задаётся (сейчас 3):
 * цикл ждёт «любой из» (C3 | «איך היה?» | «לנסות שוב» | «קראתי!») и делает следующий шаг.
 * Лимит шагов — понятная ошибка вместо зависания.
 */
export async function passReadingToResults(page: Page, rating: SelfRating = 'בסדר', maxSteps = 40) {
  const s = readingScreens(page);
  const rate = page.getByRole('button', { name: rating, exact: true });
  const done = () => /\/assessment\/results$/.test(new URL(page.url()).pathname);

  for (let step = 0; step < maxSteps; step++) {
    await expect(s.resultsTitle.or(s.howWasIt).or(s.retry).or(s.read).first()).toBeVisible({ timeout: 30_000 });
    if (done() || (await s.resultsTitle.isVisible())) {
      await page.waitForURL(/\/assessment\/results$/);
      return;
    }
    if (await s.howWasIt.isVisible()) {
      await rate.click();
      await expect(s.howWasIt).toBeHidden({ timeout: 30_000 });
    } else if (await s.retry.isVisible()) {
      await s.retry.click();
      await expect(s.howWasIt.or(s.resultsTitle).first()).toBeVisible({ timeout: 30_000 });
    } else {
      await s.read.click();
      await expect(s.retry.or(s.howWasIt).or(s.resultsTitle).first()).toBeVisible({ timeout: 30_000 });
    }
  }
  throw new Error(`Чтение не дошло до /assessment/results за ${maxSteps} шагов`);
}

/** Нет горизонтальной прокрутки: scrollWidth <= clientWidth (с ожиданием раскладки). */
export async function expectNoHorizontalScroll(page: Page, where: string) {
  await expect
    .poll(
      () => page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth),
      { message: `${where}: горизонтальная прокрутка (scrollWidth - clientWidth)`, timeout: 10_000 },
    )
    .toBeLessThanOrEqual(0);
}

/** Кнопка целиком в пределах ширины экрана. */
export async function expectInsideViewport(page: Page, locator: Locator, where: string) {
  await expect(locator).toBeVisible();
  const box = await locator.boundingBox();
  const width = page.viewportSize()?.width ?? 0;
  expect(box, `${where}: нет boundingBox`).not.toBeNull();
  expect(box!.x, `${where}: кнопка уходит за левый край`).toBeGreaterThanOrEqual(0);
  expect(box!.x + box!.width, `${where}: кнопка уходит за правый край (${width}px)`).toBeLessThanOrEqual(width);
}

/**
 * Запоминает последний запрос страницы к Supabase REST с заголовком authorization
 * (в режиме ребёнка в нём есть и x-child-session). Подключать ДО передачи устройства.
 */
export function trackSupabaseRest(page: Page) {
  let last: Request | undefined;
  page.on('request', (req) => {
    if (req.url().includes('/rest/v1/') && req.headers()['authorization']) last = req;
  });
  return {
    async auth(): Promise<{ base: string; headers: Record<string, string> }> {
      if (!last) throw new Error('Страница ещё не обращалась к Supabase REST (/rest/v1/) с authorization');
      const all = await last.allHeaders();
      const headers: Record<string, string> = {};
      for (const k of ['apikey', 'authorization', 'x-child-session', 'accept-profile']) if (all[k]) headers[k] = all[k];
      const base = last.url().split('/rest/v1/')[0];
      return { base, headers };
    },
  };
}

export interface PlacementAttempt {
  id: string;
  child_id: string;
  reading_status?: string;
  writing_status?: string;
  [k: string]: unknown;
}

/** Строки placement_attempts ребёнка (ответ должен быть 200). */
export async function fetchPlacementAttempts(
  page: Page,
  tracker: ReturnType<typeof trackSupabaseRest>,
  childId: string,
): Promise<PlacementAttempt[]> {
  const { base, headers } = await tracker.auth();
  const resp = await page.request.get(`${base}/rest/v1/placement_attempts?child_id=eq.${childId}&select=*`, { headers });
  expect(resp.status(), `placement_attempts: HTTP ${resp.status()} ${await resp.text()}`).toBe(200);
  return (await resp.json()) as PlacementAttempt[];
}
